import{z as A,x as n,o as r,c as d,q as t,j as i,D as E,d as B,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"遗赠动机","description":"","frontmatter":{"title":"遗赠动机","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bequest-motive.md","filePath":"econ/bequest-motive.md","lastUpdated":1791063341000}'),p={name:"econ/bequest-motive.md"};function m(u,a,D,f,C,c){const o=n("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="遗赠动机" tabindex="-1">遗赠动机 <a class="header-anchor" href="#遗赠动机" aria-label="Permalink to &quot;遗赠动机&quot;">​</a></h1><div class="epigraph"><p>纯生命周期在终年把财富吃完；数据里的遗产迫使我们问：那是爱、是事故，还是年金市场缺失。</p><footer>—— 对照 Yaari 1965 的不确定寿命；Barro, JPE 1974；Kotlikoff and Summers, JPE 1981；Hurd, Econometrica 1989</footer></div><p><a href="/econ/liquidity-constraints-excess-sensitivity">上一课</a>解释了年轻端的高 MPC。本课缺口转到生命终点：LCH 预测退休后负储蓄直至耗尽，但老年人仍持有大量资产并留下遗产。不重写年龄隆起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三种候选。有意遗赠：效用含继承人消费或遗产本身（利他或「遗产当奢侈品」）。Barro（1974）的王朝利他把世代链成李嘉图等价的微观基础。Kotlikoff 与 Summers（1981）估计美国财富中很大一块可追溯到代际转移，而不只是生命周期储蓄。意外遗赠：寿命不确定且年金不足，预防性多留的财富在死后剩下——Yaari（1965）已经把不确定寿命写进欧拉。Hurd（1989）用退休后的储蓄行为区分：许多老年人的边际遗赠效用接近零，意外与健康风险更重要。</p><p>缺口是给 LCH 的终点条件加一项，而不是重开永久收入定义。</p><p><span class="marginnote">策略性遗赠（Bernheim, Shleifer and Summers, 1985）用遗产交换子女的照料，已经是家庭内部博弈，本课只点名，不展开讨价还价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在有限寿命模型末项加 \\(v(b)\\)，或把继承人效用贴现进来。意外遗赠不需要 \\(v\\)：只要死亡随机且没有公平年金，最优就是持有流动性财富，死后残值归继承人。经验上比较有无子女者的退休路径、遗产的收入弹性、以及对年金的需求——下一课年金之谜正是这条线索的市场面。</p><p><span class="marginnote">术语翻译：「意外遗赠」不是说人稀里糊涂留下钱，而是寿命不确定下最优预防储蓄的副产品——没人知道自己哪天走，只能按「活得久」的预案存钱，提前离场的就把残值剩下了。</span></p>',10)),(r(),i(s,null,{default:E(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LCH%5B%22LCH%3A%20%E7%BB%88%E5%B9%B4%E8%80%97%E5%B0%BD%22%5D%20--%3E%20DATA%5B%22%E7%BB%88%E7%82%B9%E4%BB%8D%E6%9C%89%E6%AD%A3%E8%B4%A2%E5%AF%8C%22%5D%0A%20%20DATA%20--%3E%20INT%5B%22%E6%9C%89%E6%84%8F%3A%20v(b)%20%E6%88%96%E5%88%A9%E4%BB%96%22%5D%0A%20%20DATA%20--%3E%20ACC%5B%22%E6%84%8F%E5%A4%96%3A%20%E9%95%BF%E5%AF%BF%E9%A3%8E%E9%99%A9%E6%97%A0%E5%B9%B4%E9%87%91%22%5D%0A%20%20INT%20--%3E%20BARRO%5B%22%E7%8E%8B%E6%9C%9D%3A%20%E6%9D%8E%E5%98%89%E5%9B%BE%E9%93%BE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"本课不估计代际转移份额的争论（Modigliani 与 Kotlikoff 的口径之争只作为边界）。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"有意遗赠改变的是终点边际效用：少吃一单位可以换成 \\(v'(b)\\)。意外遗赠改变的是保险可能集：不能把「活得太长」卖给市场时，财富同时承担退休消费与遗产残值。两种机制对年金需求相反：纯粹利他仍可买年金再另留遗产；单纯意外遗赠会压低自愿年金——因为年金没有残值。后课用这个符号差。",-1)),(r(),i(s,null,{default:E(()=>[l(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%AD%BB%E4%BA%A1%E6%97%B6%E7%82%B9%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20ANN%5B%22%E8%83%BD%E4%B9%B0%E5%88%B0%E5%85%AC%E5%B9%B3%E5%B9%B4%E9%87%91%E5%90%97%22%5D%0A%20%20ANN%20--%3E%7C%22%E8%83%BD%22%7C%20Y%5B%22%E6%B6%88%E8%B4%B9%E5%85%A8%E9%A2%9D%E4%BF%9D%E9%99%A9%22%5D%0A%20%20ANN%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20N%5B%22%E8%B4%A2%E5%AF%8C%E5%85%BC%E4%BB%BB%E5%85%BB%E8%80%81%E9%87%91%E4%B8%8E%E6%AE%8B%E5%80%BC%22%5D%0A%20%20Y%20--%3E%20A1%5B%22%E9%81%97%E4%BA%A7%E4%BB%85%E5%BD%93%E6%9C%89%E6%84%8F%20v(b)%20%E5%AD%98%E5%9C%A8%E6%97%B6%E6%89%8D%E7%95%99%22%5D%0A%20%20N%20--%3E%20A2%5B%22%E6%AD%BB%E5%90%8E%E6%AE%8B%E5%80%BC%E8%87%AA%E5%8A%A8%E6%88%90%E4%B8%BA%E6%84%8F%E5%A4%96%E9%81%97%E8%B5%A0%22%5D%0A%20%20A2%20--%3E%20LOW%5B%22%E8%87%AA%E6%84%BF%E5%B9%B4%E9%87%91%E8%A2%AB%E5%8E%8B%E4%BD%8E%EF%BC%9A%E6%97%A0%E6%AE%8B%E5%80%BC%E5%8F%AF%E7%95%99%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>也不进入限价簿。遗产是合同与偏好，不是成交队列。主干接到簿为止，本课补的是生命终点的效用项与保险可能集。</p><p>Barro 链把利他写成每一代都关心下一代，一次总付的政府债务被私人储蓄抵消——李嘉图等价的微观故事。现场链条会断：无子女、有限利他、流动性约束的年轻人收不到补偿。Kotlikoff–Summers 的口径之争（多少财富是转移来的）不在本课仲裁；本课只要：终点条件不再是 \\(a_T=0\\) 这一条。</p><p><span class="marginnote">数字实例：把 100 万换成公平年金，活到 85 岁每年大约多领 6-7 万；若 70 岁早逝，则分文不剩。纯利他者可以「先买年金、另留一笔遗产」两头顾；担心早逝剩不下钱的人，恰恰因此不肯多买年金。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>医疗支出风险、长期护理、房产不可分，都会在终点留下资产，不必有 \\(v(b)\\)。本课不把住房提前写成下一课的全部内容，只承认住房是遗产的主要载体之一。现时偏差很少被用来解释遗产：老练自我更担心退休前被花光，而不是死后留多留少。</p><p>后课默认：终点财富有有意与意外两条通道；年金之谜要在二者之间做识别。</p><p>终点 \\(a_T=0\\) 被遗产数据拒绝之后，有意 \\(v(b)\\) 与意外残值给出相反的年金含义。</p><p>Barro 链把利他接到李嘉图；链条在无子女或流动性约束处会断。</p><p><span class="marginnote">直觉类比：Barro 王朝像一串互相投保的家庭——这一代多留遗产，是为了替下一代消化政府今天减税留下的未来账单；只要某一代「无后」或被流动性卡住拿不出补偿，内部转移链断掉，李嘉图等价随之失效。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纯 LCH 吃完财富；遗产要求有意动机或意外残值。</li><li>Barro 王朝把利他接到李嘉图；Kotlikoff–Summers 强调代际转移规模。</li><li>Hurd：许多退休路径更接近意外而非强利他。</li><li>意外遗赠不需要遗产进入效用。</li><li>住房不可分会在终点留下资产，不必先有 \\(v(b)\\)。</li><li>出处：Yaari 1965；Barro, <em>JPE</em> 1974；Kotlikoff and Summers, <em>JPE</em> 1981；Hurd, <em>Econometrica</em> 1989。</li></ul>',11))])}const _=A(p,[["render",m]]);export{b as __pageData,_ as default};
